import{_ as e,o as a,c as n,a2 as t}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Claude","description":"","frontmatter":{"title":"Claude"},"headers":[],"relativePath":"prompts/CLAUDE.md","filePath":"prompts/CLAUDE.md"}'),i={name:"prompts/CLAUDE.md"};function o(p,s,l,r,d,c){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="claude-md-—-how-to-write-fault-models" tabindex="-1">CLAUDE.md — How to Write Fault Models <a class="header-anchor" href="#claude-md-—-how-to-write-fault-models" aria-label="Permalink to &quot;CLAUDE.md — How to Write Fault Models&quot;">​</a></h1><p>Fault is a modeling language for finding failures in system designs. This file teaches you how to think about and write Fault models effectively.</p><h2 id="the-core-mindset" tabindex="-1">The Core Mindset <a class="header-anchor" href="#the-core-mindset" aria-label="Permalink to &quot;The Core Mindset&quot;">​</a></h2><p><strong>A Fault model that finds no failures is a bad model.</strong></p><p>Fault is not a proof system. It does not verify that your system is correct. It looks for scenarios where your assertions are violated. If it finds none, your assertions are too weak or your model is too simple. Keep tightening the model until it finds something interesting.</p><p>Assertions are written as things you <em>want</em> to be true. Fault negates them and asks the solver to find a counterexample. If the solver finds one, that&#39;s a result, not a failure.</p><hr><h2 id="choosing-your-file-structure" tabindex="-1">Choosing Your File Structure <a class="header-anchor" href="#choosing-your-file-structure" aria-label="Permalink to &quot;Choosing Your File Structure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Use</th></tr></thead><tbody><tr><td>Modeling a single process (how does this thing change over time?)</td><td>One <code>.fspec</code> file</td></tr><tr><td>Modeling multiple interacting components with distinct states</td><td>One <code>.fsystem</code> + one or more <code>.fspec</code> files</td></tr></tbody></table><p>Start with <code>.fspec</code> only. Add a <code>.fsystem</code> when you need to reason about <em>which mode</em> a component is in, not just <em>what values</em> it holds.</p><hr><h2 id="designing-a-model-the-process" tabindex="-1">Designing a Model: The Process <a class="header-anchor" href="#designing-a-model-the-process" aria-label="Permalink to &quot;Designing a Model: The Process&quot;">​</a></h2><h3 id="step-1-—-identify-what-can-go-wrong" tabindex="-1">Step 1 — Identify what can go wrong <a class="header-anchor" href="#step-1-—-identify-what-can-go-wrong" aria-label="Permalink to &quot;Step 1 — Identify what can go wrong&quot;">​</a></h3><p>Before writing any code, ask: what failure modes am I trying to find? What invariants would be violated if the system broke? Write these down as plain English first.</p><p>Examples:</p><ul><li>&quot;The cache should never hold more than N records&quot;</li><li>&quot;The container manager should always eventually have an active instance&quot;</li><li>&quot;Two flows shouldn&#39;t be able to corrupt shared state if run concurrently&quot;</li></ul><h3 id="step-2-—-define-your-stocks" tabindex="-1">Step 2 — Define your stocks <a class="header-anchor" href="#step-2-—-define-your-stocks" aria-label="Permalink to &quot;Step 2 — Define your stocks&quot;">​</a></h3><p>Stocks are reservoirs — things that accumulate and drain. Every variable you care about tracking over time is a stock.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def resources = stock{</span></span>
<span class="line"><span>    blocks: 0,</span></span>
<span class="line"><span>    table: 0,</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>Start with concrete numeric values. Switch to <code>unknown()</code> when you want the solver to find interesting starting conditions rather than testing from a fixed baseline.</p><h3 id="step-3-—-define-your-flows" tabindex="-1">Step 3 — Define your flows <a class="header-anchor" href="#step-3-—-define-your-flows" aria-label="Permalink to &quot;Step 3 — Define your flows&quot;">​</a></h3><p>Flows are the operations that change stocks. Group functions that affect the same stock together in one flow.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def record = flow{</span></span>
<span class="line"><span>    machine: new resources,</span></span>
<span class="line"><span>    lookup: func{</span></span>
<span class="line"><span>        machine.blocks &lt;- 1;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    release: func{</span></span>
<span class="line"><span>        machine.blocks -&gt; 1;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>};</span></span></code></pre></div><p><code>&lt;-</code> increments, <code>-&gt;</code> decrements. Flows have no return values — they are side effects by design.</p><h3 id="step-4-—-write-your-assertions" tabindex="-1">Step 4 — Write your assertions <a class="header-anchor" href="#step-4-—-write-your-assertions" aria-label="Permalink to &quot;Step 4 — Write your assertions&quot;">​</a></h3><p>Assertions should reflect the invariants you identified in step 1. Write them in terms of your stocks.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert resources.blocks &lt; 4;</span></span>
<span class="line"><span>assert pool.instances &gt; 0 eventually-always;</span></span></code></pre></div><p>If you&#39;re not sure what to assert, ask: what would have to be true for this system to be working correctly? Assert that. Fault will try to find a case where it isn&#39;t.</p><h3 id="step-5-—-write-your-run-block" tabindex="-1">Step 5 — Write your run block <a class="header-anchor" href="#step-5-—-write-your-run-block" aria-label="Permalink to &quot;Step 5 — Write your run block&quot;">​</a></h3><p>The run block defines the sequence of steps to verify. Each line is one round. Use <code>|</code> to test concurrent execution. Instantiate your flows in the <code>init</code> section.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run init {</span></span>
<span class="line"><span>    r = new record;</span></span>
<span class="line"><span>} {</span></span>
<span class="line"><span>    r.store | r.release;</span></span>
<span class="line"><span>    r.store | r.release;</span></span>
<span class="line"><span>    r.store | r.release;</span></span>
<span class="line"><span>    r.store | r.release;</span></span>
<span class="line"><span>    r.store | r.release;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>The number of steps should be enough for interesting state to accumulate. Start with 3–5 and increase if the failure you&#39;re looking for requires more steps to manifest.</p><h3 id="step-6-—-add-a-state-machine-if-needed" tabindex="-1">Step 6 — Add a state machine (if needed) <a class="header-anchor" href="#step-6-—-add-a-state-machine-if-needed" aria-label="Permalink to &quot;Step 6 — Add a state machine (if needed)&quot;">​</a></h3><p>If your system has distinct operating modes (idle, processing, error, etc.), add a <code>.fsystem</code> and import your <code>.fspec</code> files into it. The state machine defines <em>which</em> flows get triggered and <em>when</em>.</p><hr><h2 id="syntax-quick-reference" tabindex="-1">Syntax Quick Reference <a class="header-anchor" href="#syntax-quick-reference" aria-label="Permalink to &quot;Syntax Quick Reference&quot;">​</a></h2><h3 id="operators" tabindex="-1">Operators <a class="header-anchor" href="#operators" aria-label="Permalink to &quot;Operators&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Op</th><th>Meaning</th><th>Where</th></tr></thead><tbody><tr><td><code>&lt;-</code></td><td>Increment stock</td><td>flow functions only</td></tr><tr><td><code>-&gt;</code></td><td>Decrement stock</td><td>flow functions only</td></tr><tr><td><code>=</code></td><td>Overwrite stock value</td><td>flow functions only</td></tr><tr><td><code>||</code></td><td>Non-deterministic choice</td><td>state functions</td></tr><tr><td><code>|</code></td><td>Concurrent execution</td><td>run block</td></tr><tr><td><code>::count</code></td><td>Count instances of a <code>multiple</code> flow</td><td><code>assume l::count &lt; 5</code></td></tr><tr><td><code>when A then B</code></td><td>Conditional invariant (A implies B)</td><td><code>assert</code>/<code>assume</code> only</td></tr><tr><td><code>advance(this.state)</code></td><td>Transition to state</td><td>state functions</td></tr><tr><td><code>advance(other.state)</code></td><td>Cross-component transition</td><td>state functions</td></tr><tr><td><code>stay()</code></td><td>Remain in current state</td><td>state functions</td></tr><tr><td><code>leave()</code></td><td>Exit current state</td><td>state functions</td></tr></tbody></table><h3 id="data-types" tabindex="-1">Data Types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Example</th><th>Notes</th></tr></thead><tbody><tr><td>numeric</td><td><code>blocks: 0</code></td><td>All numbers become reals internally</td></tr><tr><td>boolean</td><td><code>active: true</code></td><td></td></tr><tr><td>unknown</td><td><code>blocks</code> or <code>blocks: unknown()</code></td><td>Solver picks any value</td></tr><tr><td>uncertain</td><td><code>blocks: uncertain(1, 0.5)</code></td><td>Normal dist, mean + sigma; returns probabilities</td></tr><tr><td>string</td><td><code>s = &quot;description&quot;</code></td><td>Treated as a boolean in logic expressions</td></tr><tr><td><code>int()</code></td><td><code>offset: int()</code></td><td>Solver picks any integer</td></tr><tr><td><code>float()</code></td><td><code>reading: float()</code></td><td>Solver picks any float</td></tr><tr><td><code>bool()</code></td><td><code>flag: bool()</code></td><td>Solver picks true or false</td></tr><tr><td><code>natural(n)</code></td><td><code>size: natural(0)</code></td><td>Non-negative integer starting from n</td></tr><tr><td><code>whole()</code></td><td><code>ticks: whole()</code></td><td>Non-negative integer, unconstrained start</td></tr><tr><td><code>param()</code></td><td><code>threshold: param()</code></td><td>Template parameter — filled in by <code>fault render</code></td></tr></tbody></table><h3 id="temporal-qualifiers-for-assertions" tabindex="-1">Temporal Qualifiers for Assertions <a class="header-anchor" href="#temporal-qualifiers-for-assertions" aria-label="Permalink to &quot;Temporal Qualifiers for Assertions&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert x &gt; 0;                    // must hold at some point (default)</span></span>
<span class="line"><span>assert x &gt; 0 always;             // must hold at every step</span></span>
<span class="line"><span>assert x &gt; 0 eventually;         // must hold at least once</span></span>
<span class="line"><span>assert x &gt; 0 eventually-always;  // must hold once, then keep holding</span></span>
<span class="line"><span>assert x &gt; 0 nmt 3;              // must hold no more than 3 times</span></span>
<span class="line"><span>assert x &gt; 0 nft 2;              // must hold no fewer than 2 times</span></span>
<span class="line"><span>assume myFunc available;         // unfunc precondition is satisfiable from initial state</span></span></code></pre></div><h3 id="state-functions" tabindex="-1">State Functions <a class="header-anchor" href="#state-functions" aria-label="Permalink to &quot;State Functions&quot;">​</a></h3><p>State functions use a restricted body — only state steps are valid, not arbitrary expressions:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>component foo = states{</span></span>
<span class="line"><span>    idle: sfunc{</span></span>
<span class="line"><span>        advance(this.active) || advance(this.expired);</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    active: sfunc{</span></span>
<span class="line"><span>        someFlow.method;</span></span>
<span class="line"><span>        if someFlow.stock.value &gt; 5 {</span></span>
<span class="line"><span>            advance(this.idle);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    expired: sfunc{</span></span>
<span class="line"><span>        stay();</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>States can be referenced as booleans in conditions: <code>if !foo.expired { ... }</code></p><h3 id="stock-inheritance" tabindex="-1">Stock Inheritance <a class="header-anchor" href="#stock-inheritance" aria-label="Permalink to &quot;Stock Inheritance&quot;">​</a></h3><p>A stock can inherit all fields from another using <code>extends</code>. Use <code>exclude</code> to drop specific fields.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def base = stock{</span></span>
<span class="line"><span>    value: 0,</span></span>
<span class="line"><span>    limit: 100,</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def extended = stock{</span></span>
<span class="line"><span>    extends base,        // inherits value and limit</span></span>
<span class="line"><span>    extra: 5,</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def minimal = stock{</span></span>
<span class="line"><span>    extends base,</span></span>
<span class="line"><span>    exclude limit,       // inherits value only</span></span>
<span class="line"><span>};</span></span></code></pre></div><hr><h3 id="declarative-functions-unfunc" tabindex="-1">Declarative Functions: <code>unfunc</code> <a class="header-anchor" href="#declarative-functions-unfunc" aria-label="Permalink to &quot;Declarative Functions: \`unfunc\`&quot;">​</a></h3><p><code>unfunc</code> replaces <code>func</code> when you want to declare preconditions and effects rather than write imperative steps. Used with program synthesis.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def ops = flow{</span></span>
<span class="line"><span>    q: new queue,</span></span>
<span class="line"><span>    process: unfunc{</span></span>
<span class="line"><span>        requires q.pending &gt; 0,    // precondition</span></span>
<span class="line"><span>        emits q.pending -&gt; 1,      // effect: decrement</span></span>
<span class="line"><span>        emits q.done &lt;- 1,         // effect: increment</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>};</span></span></code></pre></div><p><code>requires</code> — solver only selects this function when the condition holds. <code>emits</code> — declares an effect. Supports <code>=</code>, <code>&lt;-</code>, <code>-&gt;</code>.</p><hr><h3 id="program-synthesis" tabindex="-1">Program Synthesis <a class="header-anchor" href="#program-synthesis" aria-label="Permalink to &quot;Program Synthesis&quot;">​</a></h3><p>Use <code>__</code> (synthesis slots) in the run block and <code>assume</code> (not <code>assert</code>) as goals. The solver fills each slot with a function call that satisfies the goal.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Goal: find ops that reach balance &gt; 100</span></span>
<span class="line"><span>assume wallet.balance &gt; 100 eventually;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>run init {</span></span>
<span class="line"><span>    acct = new ops;</span></span>
<span class="line"><span>} {</span></span>
<span class="line"><span>    __;</span></span>
<span class="line"><span>    __;</span></span>
<span class="line"><span>    __;</span></span>
<span class="line"><span>    __;</span></span>
<span class="line"><span>    __;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>Key rules:</p><ul><li><code>__</code> slots are independent — the solver may pick a different function for each</li><li>Use <code>assume</code> for synthesis goals, never <code>assert</code> (assert looks for violations, assume restricts to satisfying solutions)</li><li>Mix explicit steps and <code>__</code> freely: <code>acct.deposit; __; __;</code></li><li>If the goal is unreachable in the given number of steps, the solver returns <code>unsat</code> — add more <code>__</code> slots</li></ul><hr><h3 id="imports-fsystem-only" tabindex="-1">Imports (fsystem only) <a class="header-anchor" href="#imports-fsystem-only" aria-label="Permalink to &quot;Imports (fsystem only)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import(</span></span>
<span class="line"><span>    &quot;cache.fspec&quot;</span></span>
<span class="line"><span>    &quot;orchestrator.fspec&quot;</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>global record = new cache.record;</span></span>
<span class="line"><span>global manager = new orchestrator.control;</span></span></code></pre></div><p>Only <code>.fsystem</code> files can import. One level only — specs cannot import other specs.</p><hr><h2 id="running-fault" tabindex="-1">Running Fault <a class="header-anchor" href="#running-fault" aria-label="Permalink to &quot;Running Fault&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Full model check (requires SOLVERCMD and SOLVERARG env vars or ~/.faultrc)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.fspec</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate SMT only (no solver required — good for checking syntax)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.fspec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Type-check without compiling</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.fspec</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check reachability — are all states reachable from start?</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.fsystem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --complete</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Inspect the AST (useful for debugging parse issues)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.fspec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ast</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># JSON output (result to stdout, warnings to stderr)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fault</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.fspec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>Required environment for model checking:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SOLVERCMD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;z3&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SOLVERARG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-in&quot;</span></span></code></pre></div><p>Without these set, Fault returns an error in model mode. Use <code>-m smt</code> with <code>--output smt</code> to inspect generated SMT without a solver.</p><hr><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><p><strong>Assertions that are too easy to satisfy</strong> If the solver immediately finds a violation at step 0, your initial stock values may already violate the assertion. Start stocks at values that represent normal operation.</p><p><strong>Assertions that are impossible to violate</strong> If the model returns no result (unsat), either the assertion is vacuously true given your model, or you need more steps in the run block, more concurrent flows, or weaker assumptions.</p><p><strong>Forgetting that <code>|</code> generates all orderings</strong><code>a.fn | b.fn | c.fn</code> generates 6 permutations. Three concurrent flows is usually enough — more than that makes the SMT very large.</p><p><strong>Mixing up <code>&lt;-</code> and <code>-&gt;</code></strong><code>&lt;-</code> is increment (stock receives). <code>-&gt;</code> is decrement (stock releases). Think of the arrow as showing direction of flow into or out of the stock.</p><p><strong>State functions that do nothing</strong><code>stay()</code> is optional but make state bodies non-empty — the compiler rejects empty function/state blocks.</p><p><strong>Variable names with underscores</strong> Not supported. Use camelCase.</p><p><strong>Using <code>assert</code> as a synthesis goal</strong> In synthesis mode, <code>assert</code> looks for violations — it will immediately find a counterexample at the initial state if the condition isn&#39;t trivially satisfied. Use <code>assume</code> to express what you want the solver to find. <code>assert</code> is for safety properties; <code>assume</code> is for synthesis goals.</p><p><strong>Assuming imported spec run blocks execute</strong> When a <code>.fspec</code> is imported into a <code>.fsystem</code>, its run block is ignored. Only its stock/flow definitions and assertions carry over. Define your run block in the <code>.fsystem</code> or in the standalone <code>.fspec</code>.</p><hr><h2 id="a-complete-minimal-example" tabindex="-1">A Complete Minimal Example <a class="header-anchor" href="#a-complete-minimal-example" aria-label="Permalink to &quot;A Complete Minimal Example&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spec queue;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def buffer = stock{</span></span>
<span class="line"><span>    size: 0,</span></span>
<span class="line"><span>    capacity: 10,</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def ops = flow{</span></span>
<span class="line"><span>    q: new buffer,</span></span>
<span class="line"><span>    enqueue: func{</span></span>
<span class="line"><span>        q.size &lt;- 1;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    dequeue: func{</span></span>
<span class="line"><span>        q.size -&gt; 1;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>assert buffer.size &lt; buffer.capacity;</span></span>
<span class="line"><span>assert buffer.size &gt;= 0;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>run init {</span></span>
<span class="line"><span>    w = new ops;</span></span>
<span class="line"><span>} {</span></span>
<span class="line"><span>    w.enqueue | w.dequeue;</span></span>
<span class="line"><span>    w.enqueue | w.dequeue;</span></span>
<span class="line"><span>    w.enqueue | w.dequeue;</span></span>
<span class="line"><span>    w.enqueue | w.dequeue;</span></span>
<span class="line"><span>    w.enqueue | w.dequeue;</span></span>
<span class="line"><span>    w.enqueue | w.dequeue;</span></span>
<span class="line"><span>    w.enqueue | w.dequeue;</span></span>
<span class="line"><span>    w.enqueue | w.dequeue;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>This asks: can concurrent enqueue/dequeue operations push the queue past capacity or below zero? The <code>|</code> operator makes Fault try both orderings each round.</p>`,84)])])}const f=e(i,[["render",o]]);export{u as __pageData,f as default};
